window.kbPageData["views/entry/k-d5a77d2fbd4be1eb"] = {"key":"entry/k-d5a77d2fbd4be1eb","state":{"route":"entry/k-d5a77d2fbd4be1eb"},"node":{"id":"k-d5a77d2fbd4be1eb","mode":"k","title":"望而却步与裹足不前","type":"概念与词义","domain":"汉语","reading":"","intro":"","priority":100,"aliases":["望而却步与裹足不前的词义辨析"],"qs":["国考 2024 地市级 行测#33"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"望而却步指看到危险或自觉难以应付的情形便退缩。裹足不前指因有所顾虑而停步，迟迟不敢行动。","review":{"definition":"望而却步指看到危险或自觉难以应付的情形便退缩。裹足不前指因有所顾虑而停步，迟迟不敢行动。","explanation":"第33题以少数船只“敢于一试身手”反衬绝大部分战舰面对巨大海冰时不敢贸然前进。“望而却步”突出面对眼前障碍而退缩，“裹足不前”突出因顾虑而止步，两者都能承接第一空的对照。最终由第二空的“轻而易举”确定选A。","references":[],"evidence":"唯有破冰船和冰面下的潜艇敢于一试身手","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2024 地市级 行测#33":{"paper":"国考 2024 地市级 行测","n":33,"mod":"言语理解与表达","src":["92d0b72e86a6a33d568d.pdf",6],"asrc":["e1792c53900a45f1b9fa.pdf",11],"card":"b7b90bcf6b9bdfcfa897fa1f","links":[{"id":"k-d5a77d2fbd4be1eb","role":"解题依据","why":"望而却步强调见到危险或困难后退缩，裹足不前强调因顾虑而止步，两者均可表达第一空的不敢尝试。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-d5a77d2fbd4be1eb":[["国考 2024 地市级 行测#33"]]}};
